import {_electron as electron} from 'playwright';
import {mkdtemp,readFile,realpath,mkdir} from 'node:fs/promises';import os from 'node:os';import path from 'node:path';import assert from 'node:assert/strict';
const data=await mkdtemp(path.join(os.tmpdir(),'nodus-first-work-')),desktop=path.join(await mkdtemp(path.join(os.tmpdir(),'nodus-delivery-home-')),'Desktop');await mkdir(desktop);let output=await realpath(desktop);
const evidence=await mkdtemp(path.join(process.env.RUNNER_TEMP||os.tmpdir(),'nodus-delivery-evidence-'));
const html=`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>飞机大战测试作品</title><style>body{margin:0;background:#111827;color:white;font:18px sans-serif;text-align:center}canvas{background:#18243b;display:block;margin:20px auto;border:1px solid #7185aa}button{padding:10px 24px}</style></head><body><h1>飞机大战</h1><button id="start">开始游戏</button><p>方向键移动，空格发射</p><canvas width="320" height="300" id="game"></canvas><p id="status">尚未开始</p><script>const c=document.querySelector('canvas'),ctx=c.getContext('2d');let x=160,shots=0,playing=false;function draw(){ctx.clearRect(0,0,320,300);ctx.fillStyle='#70caff';ctx.beginPath();ctx.moveTo(x,230);ctx.lineTo(x-15,260);ctx.lineTo(x+15,260);ctx.fill();ctx.fillStyle='#ffce70';ctx.fillRect(150,35,25,18);for(let i=0;i<shots;i++)ctx.fillRect(x-2,195-i*14,4,10);c.dataset.x=x;c.dataset.shots=shots;}document.querySelector('#start').onclick=()=>{playing=true;document.querySelector('#status').textContent='游戏进行中';draw()};onkeydown=e=>{if(!playing)return;if(e.key==='ArrowRight')x=Math.min(300,x+20);if(e.key==='ArrowLeft')x=Math.max(20,x-20);if(e.code==='Space')shots++;e.preventDefault();draw()};draw();</script></body></html>`;
const app=await electron.launch({executablePath:process.env.NODUS_QA_EXE,args:[`--user-data-dir=${data}/profile`],env:{...process.env,NODUS_DATA_DIR:data}});
try{
 if(process.platform==='win32'){const home=await app.evaluate(({app})=>app.getPath('desktop'));await mkdir(home,{recursive:true});output=await realpath(await mkdtemp(path.join(home,'Nodus-QA-')));}
 const page=await app.firstWindow();await page.locator('#requirementInput').waitFor();
 await app.evaluate(({ipcMain,app,dialog,shell,Notification,BrowserWindow},payload)=>{
  globalThis.taskAlerts=[];globalThis.nativeNoticeEvents=[];globalThis.attentionCalls=0;const originalShow=Notification.prototype.show;Notification.prototype.show=function(){globalThis.taskAlerts.push({title:this.title,body:this.body});this.on('show',()=>globalThis.nativeNoticeEvents.push('shown'));this.on('failed',()=>globalThis.nativeNoticeEvents.push('failed'));return originalShow.call(this);};const win=BrowserWindow.getAllWindows()[0],flash=win.flashFrame.bind(win);win.flashFrame=value=>{if(value)globalThis.attentionCalls++;return flash(value);};win.minimize();globalThis.openedFiles=[];shell.openPath=async file=>{globalThis.openedFiles.push(file);return '';};globalThis.artifactWrites=0;globalThis.chatCalls=0;globalThis.selectedPaths=[];
  dialog.showOpenDialog=async()=>{globalThis.selectedPaths.push(payload.output);return{canceled:false,filePaths:[payload.output]};};
  const boot=ipcMain._invokeHandlers.get('forma:bootstrap');ipcMain.removeHandler('forma:bootstrap');ipcMain.handle('forma:bootstrap',async(...args)=>{const r=await boot(...args);r.model.configured=true;r.model.modelId='Scripted test provider';return r;});
  ipcMain.removeHandler('forma:one-shot-chat');ipcMain.handle('forma:one-shot-chat',()=>{globalThis.chatCalls++;return '普通聊天答复';});
  const require=process.getBuiltinModule('node:module').createRequire(app.getAppPath()+'/package.json');const {PiService}=require(app.getAppPath()+'/backend/pi-service.mjs');
  PiService.prototype.requireModel=()=>{};PiService.prototype.runText=async args=>{
   if(args.phase==='options')return JSON.stringify({artifactType:'website',question:'选择游戏方向',options:[1,2,3,4].map(id=>({id:String(id),title:'方向'+id,description:'飞机大战',effect:'可在浏览器打开',tradeoff:'简单图形',condition:'本地运行'}))});
   if(args.phase==='requirement-audit')return '{"results":[]}';
   globalThis.artifactWrites++;await require('node:fs/promises').writeFile(require('node:path').join(args.cwd,'index.html'),payload.html);return '作品已生成';
  };
 },{html,output});
 await page.reload();await page.locator('#requirementInput').fill('做一个飞机大战游戏');
 await page.locator('#requirementInput').press('Shift+Enter');assert((await page.locator('#requirementInput').inputValue()).includes('\n'));await page.locator('#requirementInput').fill('做一个飞机大战游戏');
 await page.locator('#requirementInput').evaluate(e=>e.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',isComposing:true,bubbles:true,cancelable:true})));assert.equal(await app.evaluate(()=>globalThis.artifactWrites),0);assert.equal(await page.locator('#requirementInput').inputValue(),'做一个飞机大战游戏');
 await page.locator('#requirementInput').press('Enter');await page.locator('[data-choice="1"]').waitFor();assert.equal(await app.evaluate(()=>globalThis.chatCalls),0,'create request must not go to answer-only chat');
 await page.locator('[data-choice="1"]').check();await page.locator('#submitDecision').click();await page.locator('#acceptWork').waitFor();await page.locator('#saveState').filter({hasText:'已保存'}).waitFor();
 for(let i=0;i<80&&!await app.evaluate(()=>globalThis.taskAlerts.length);i++)await page.waitForTimeout(25);const notices=await app.evaluate(()=>({requested:globalThis.taskAlerts.length,events:globalThis.nativeNoticeEvents,attention:globalThis.attentionCalls}));assert(notices.attention>=1,'background completion must request taskbar attention');assert(notices.requested<=1,'at most one notification');await app.evaluate(({BrowserWindow})=>BrowserWindow.getAllWindows()[0].restore());
 const task=JSON.parse(await readFile(path.join(data,'state.json'),'utf8')).tasks[0],delivery=task.versions[0].delivery;assert(delivery.entry.startsWith(output+path.sep));assert.equal(path.extname(delivery.entry),'.html');assert.equal(await readFile(delivery.entry,'utf8'),html);assert.equal(await app.evaluate(()=>globalThis.artifactWrites),1);
 await page.locator('#openDeliveredWork').click();for(let i=0;i<80&&!await app.evaluate(()=>globalThis.openedFiles.length);i++)await page.waitForTimeout(25);assert.equal((await app.evaluate(()=>globalThis.openedFiles)).at(-1),delivery.entry);
 await page.locator('#dialogLauncher').click();await page.locator('#dialogInput').fill('把这个游戏放在我的桌面');await page.locator('#sendDialog').click();await page.getByText(/V1 已导出到/).waitFor();assert.equal(await app.evaluate(()=>globalThis.artifactWrites),1,'export must not rebuild or use answer-only chat');assert.equal(await app.evaluate(()=>globalThis.chatCalls),0);
 await page.screenshot({path:path.join(evidence,'delivered.png')});
 const opened=app.waitForEvent('window');await app.evaluate(async({BrowserWindow},file)=>{const w=new BrowserWindow({width:600,height:640,webPreferences:{sandbox:true,contextIsolation:true,nodeIntegration:false}});await w.loadFile(file);},delivery.entry);const game=await opened;const errors=[];game.on('pageerror',e=>errors.push(e.message));await game.locator('#start').click();await game.keyboard.press('ArrowRight');await game.keyboard.press('Space');assert.equal(await game.locator('#game').getAttribute('data-x'),'180');assert.equal(await game.locator('#game').getAttribute('data-shots'),'1');assert.equal(await game.locator('#status').innerText(),'游戏进行中');assert.deepEqual(errors,[]);await game.screenshot({path:path.join(evidence,'exported-game.png')});
 const result={passed:true,evidence,notices:await app.evaluate(()=>({requested:globalThis.taskAlerts.length,events:globalThis.nativeNoticeEvents,attention:globalThis.attentionCalls})),naturalLanguageCreate:true,enterSends:true,shiftEnterNewline:true,imeDoesNotSubmit:true,realNativeExport:true,exportedHtmlRuns:true,keyboardMovementAndShooting:true,backgroundCompletionDispatch:true,provider:'scripted; not a live model quality evaluation'};await (await import('node:fs/promises')).writeFile(path.join(evidence,'result.json'),JSON.stringify(result,null,2));console.log(JSON.stringify(result));
}finally{await app.close();}
